package in.foodcart.api; import in.foodcart.data.*; import in.foodcart.service.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final CheckoutService checkout;private final AuthService auth;private final OrderRepository orders;private final in.foodcart.service.payments.PaymentService payments;private final VendorRepository vendors;public OrderController(CheckoutService c,AuthService a,OrderRepository o,in.foodcart.service.payments.PaymentService p,VendorRepository v){checkout=c;auth=a;orders=o;payments=p;vendors=v;}/** Creates the order unpaid and starts the payment; the order reaches the vendor once the payment is confirmed. */ @PostMapping public java.util.Map<String,Object> create(@RequestHeader("Authorization") String header,@RequestBody CheckoutService.Request request){OrderEntity o=checkout.create(auth.actor(header,"CUSTOMER"),request);in.foodcart.service.payments.PaymentService.Started payment=payments.start(o);return java.util.Map.of("order",o,"payment",payment);}/** The customer's own order, for the status page. The stall's phone is shared only once the order is paid. */
  @GetMapping("/{id}") public java.util.Map<String,Object> get(@RequestHeader("Authorization") String header,@PathVariable String id){String customer=auth.actor(header,"CUSTOMER");OrderEntity o=orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));if(!o.customerId.equals(customer))throw new SecurityException("Order not found");
    java.util.Map<String,Object> vendor=new java.util.LinkedHashMap<>();vendors.findById(o.vendorId).ifPresent(v->{vendor.put("name",v.name);vendor.put("slug",v.slug);vendor.put("address",v.address);if(v.location!=null&&v.location.lat!=null){vendor.put("lat",v.location.lat);vendor.put("lng",v.location.lng);}boolean paid=o.status!=in.foodcart.domain.OrderStatus.PAYMENT_PENDING&&o.status!=in.foodcart.domain.OrderStatus.EXPIRED;if(paid)vendor.put("phone",v.mobile);});
    java.util.Map<String,Object> result=new java.util.LinkedHashMap<>();result.put("order",o);result.put("vendor",vendor);return result;}}
